                                                                                                                'сродници: '
                                                                                                                '"защото, '
                                                                                                                'който '
                                                                                                                'изпълни '
                                                                                                                'волята '
                                                                                                                'Божия, '
                                                                                                                'той '
                                                                                                                'Ми е '
                                                                                                                'брат, '
                                                                                                                'и '
                                                                                                                'сестра, '
                                                                                                                'и '
                                                                                                                'майка". '
                                                                                                                'Давид '
                                                                                                                'служил '
                                                                                                                'на '
                                                                                                                'тази '
                                                                                                                'воля '
                                                                                                                'на '
                                                                                                                'престола, '
                                                                                                                'Йосиф '
                                                                                                                '- в '
                                                                                                                'работилницата, '
                                                                                                                'а '
                                                                                                                'Яков '
                                                                                                                '- '
                                                                                                                'пред '
                                                                                                                'олтара, '
                                                                                                                'и '
                                                                                                                'кръвното '
                                                                                                                'им '
                                                                                                                'родство '
