                                                                                                                'увенчано '
                                                                                                                'единствено '
                                                                                                                'от '
                                                                                                                'родството '
                                                                                                                'им в '
                                                                                                                'послушанието. '
                                                                                                                'Блажени '
                                                                                                                'са '
                                                                                                                'онези, '
                                                                                                                'които, '
