                                                                                                                           'килия '
                                                                                                                           'и '
                                                                                                                           'храм '
                                                                                                                           'на '
                                                                                                                           'това '
                                                                                                                           'място, '
                                                                                                                           'открил '
                                                                                                                           'съда '
                                                                                                                           'и '
                                                                                                                           'по '
                                                                                                                           'знаменията '
                                                                                                                           'и '
                                                                                                                           'чудесата, '
                                                                                                                           'съпътстващи '
                                                                                                                           'находката, '
                                                                                                                           'разбрал '
                                                                                                                           'какво '
                                                                                                                           'съкровище '
                                                                                                                           'е '
                                                                                                                           'намерил. '
