                                                                                                                           'го '
                                                                                                                           'почитал '
                                                                                                                           'през '
                                                                                                                           'целия '
                                                                                                                           'си '
                                                                                                                           'живот, '
                                                                                                                           'а '
                                                                                                                           'преди '
                                                                                                                           'смъртта '
                                                                                                                           'си, '
                                                                                                                           'виждайки, '
                                                                                                                           'че '
                                                                                                                           'Църквата '
                                                                                                                           'навлиза '
                                                                                                                           'във '
                                                                                                                           'време '
                                                                                                                           'на '
                                                                                                                           'гонение, '
                                                                                                                           'отново '
                                                                                                                           'скрил '
                                                                                                                           'главата '
                                                                                                                           'в '
                                                                                                                           'земята '
                                                                                                                           'на '
                                                                                                                           'своя '
                                                                                                                           'храм. '
                                                                                                                           'Когато '
                                                                                                                           'постройките '
                                                                                                                           'се '
                                                                                                                           'разрушили, '
                                                                                                                           'тя '
                                                                                                                           'пак '
                                                                                                                           'изчезнала '
                                                                                                                           'от '
                                                                                                                           'човешката '
                                                                                                                           'памет. '
                                                                                                                           'Второто '
                                                                                                                           'обретение '
                                                                                                                           'принадлежи '
                                                                                                                           'към '
                                                                                                                           '452 '
                                                                                                                           'година '
                                                                                                                           'и '
                                                                                                                           'Емеса '
                                                                                                                           'в '
                                                                                                                           'Сирия. '
                                                                                                                           'Пренесена '
                                                                                                                           'там '
                                                                                                                           'през '
                                                                                                                           'изминалите '
                                                                                                                           'векове '
                                                                                                                           'от '
                                                                                                                           'ръце '
                                                                                                                           'и '
                                                                                                                           'достойни, '
                                                                                                                           'и '
                                                                                                                           'недостойни '
                                                                                                                           '- '
                                                                                                                           'на '
                                                                                                                           'монаси, '
                                                                                                                           'тайни '
                                                                                                                           'вярващи '
                                                                                                                           'и '
                                                                                                                           'дори, '
                                                                                                                           'както '
                                                                                                                           'разказва '
                                                                                                                           'повествованието, '
                                                                                                                           'на '
                                                                                                                           'един '
                                                                                                                           'арианин, '
                                                                                                                           'който '
                                                                                                                           'използвал '
                                                                                                                           'чудесата '
                                                                                                                           'ѝ '
                                                                                                                           '- '
                                                                                                                           'главата '
                                                                                                                           'лежала '
                                                                                                                           'скрита '
                                                                                                                           'в '
                                                                                                                           'пещера '
                                                                                                                           'край '
                                                                                                                           'града. '
                                                                                                                           'Тогава '
                                                                                                                           'самият '
                                                                                                                           'Предтеча '
                                                                                                                           'се '
                                                                                                                           'явил '
                                                                                                                           'във '
                                                                                                                           'видение '
                                                                                                                           'на '
                                                                                                                           'архимандрит '
                                                                                                                           'Маркел '
                                                                                                                           'от '
                                                                                                                           'тамошния '
                                                                                                                           'манастир '
                                                                                                                           'и '
                                                                                                                           'му '
                                                                                                                           'открил '
                                                                                                                           'мястото. '
                                                                                                                           'Главата '
                                                                                                                           'била '
                                                                                                                           'намерена '
                                                                                                                           'в '
                                                                                                                           'своя '
                                                                                                                           'съд, '
                                                                                                                           'посрещната '
                                                                                                                           'от '
                                                                                                                           'епископ '
                                                                                                                           'Ураний '
                                                                                                                           'с '
                                                                                                                           'целия '
                                                                                                                           'град '
                                                                                                                           'и '
                                                                                                                           'положена '
                                                                                                                           'в '
                                                                                                                           'Емеса, '
                                                                                                                           'където '
                                                                                                                           'бил '
                                                                                                                           'установен '
                                                                                                                           'празникът '
                                                                                                                           'ѝ '
                                                                                                                           'и '
                                                                                                                           'потекли '
                                                                                                                           'изцеления. '
                                                                                                                           'На '
                                                                                                                           'двадесет '
                                                                                                                           'и '
                                                                                                                           'четвърти '
                                                                                                                           'февруари '
                                                                                                                           'двете '
                                                                                                                           'обретения '
                                                                                                                           'се '
                                                                                                                           'честват '
                                                                                                                           'заедно, '
                                                                                                                           'както '
                                                                                                                           'по-късно '
                                                                                                                           'Църквата '
                                                                                                                           'ще '
                                                                                                                           'чества '
                                                                                                                           'и '
                                                                                                                           'трето. '
                                                                                                                           'Над '
                                                                                                                           'този '
                                                                                                                           'празник '
                                                                                                                           'Църквата '
                                                                                                                           'съзерцава '
                                                                                                                           'продължаващото '
                                                                                                                           'служение '
                                                                                                                           'на '
                                                                                                                           'Предтечата '
                                                                                                                           '- '
                                                                                                                           'гласът '
                                                                                                                           'на '
                                                                                                                           'викащия, '
                                                                                                                           'който '
                                                                                                                           'мечът '
                                                                                                                           'не '
                                                                                                                           'заглушил, '
                                                                                                                           'а '
                                                                                                                           'разнесъл '
                                                                                                                           'през '
                                                                                                                           'историята '
                                                                                                                           'и '
                                                                                                                           'който '
                                                                                                                           'излиза '
                                                                                                                           'наяве '
                                                                                                                           'винаги '
                                                                                                                           'когато '
                                                                                                                           'някоя '
                                                                                                                           'епоха '
                                                                                                                           'отново '
                                                                                                                           'се '
                                                                                                                           'нуждае '
                                                                                                                           'от '
                                                                                                                           'проповедта '
                                                                                                                           'на '
                                                                                                                           'отсечената '
                                                                                                                           'глава, '
                                                                                                                           'че '
